cpp.setup:
auto* scene = new fluent::layout::Card(%PARENT%);
scene->setGeometry(0, 0, 520, 300);
auto* control = new fluent::collections::DrawerView(%PARENT%);
control->setAnimationEnabled(false);
control->setEdge(fluent::collections::DrawerView::DrawerEdge::Right);
control->setDrawerLength(240);
auto* sceneLayout = new QVBoxLayout(scene);
sceneLayout->setContentsMargins(20, 16, 20, 16);
sceneLayout->setSpacing(8);
auto* heading = new fluent::textfields::Label(QStringLiteral("Project files"), scene);
heading->setFluentTypography(Typography::FontRole::Subtitle);
sceneLayout->addWidget(heading);
auto* caption = new fluent::textfields::Label(QStringLiteral("Workspace / 3 documents"), scene);
caption->setTextColorRole(fluent::textfields::Label::TextColorRole::Secondary);
sceneLayout->addWidget(caption);
for (const auto& name : {QStringLiteral("Design guidelines"), QStringLiteral("Component library"), QStringLiteral("Release notes")}) {
    auto* file = new fluent::textfields::Label(name, scene);
    file->setMinimumHeight(30);
    sceneLayout->addWidget(file);
}
sceneLayout->addStretch();
auto* openButton = new fluent::basicinput::Button(QStringLiteral("View details"), scene);
openButton->setObjectName(QStringLiteral("drawerOpen"));
openButton->setFluentStyle(fluent::basicinput::Button::Accent);
sceneLayout->addWidget(openButton, 0, Qt::AlignLeft);
auto* panel = new QWidget;
auto* panelLayout = new QVBoxLayout(panel);
panelLayout->setContentsMargins(12, 12, 12, 12);
panelLayout->setSpacing(8);
auto* header = new QHBoxLayout;
auto* title = new fluent::textfields::Label(QStringLiteral("Details"), panel);
title->setFluentTypography(Typography::FontRole::BodyStrong);
header->addWidget(title, 1);
auto* closeButton = new fluent::basicinput::Button(panel);
closeButton->setObjectName(QStringLiteral("drawerClose"));
closeButton->setAccessibleName(QStringLiteral("Close drawer"));
closeButton->setIconGlyph(Typography::Icons::ChromeClose);
closeButton->setFluentLayout(fluent::basicinput::Button::IconOnly);
closeButton->setFluentStyle(fluent::basicinput::Button::Subtle);
closeButton->setFixedSize(28, 28);
header->addWidget(closeButton);
panelLayout->addLayout(header);
auto* scroll = new fluent::scrolling::ScrollView(panel);
scroll->setWidgetResizable(true);
scroll->setVerticalScrollBarVisibility(fluent::scrolling::ScrollView::ScrollBarVisibility::Visible);
scroll->setHorizontalScrollMode(fluent::scrolling::ScrollView::ScrollMode::Disabled);
scroll->setSizePolicy(QSizePolicy::Expanding, QSizePolicy::Ignored);
auto* details = new fluent::layout::Card;
details->setBorderVisible(false);
auto* detailsLayout = new QVBoxLayout(details);
detailsLayout->setContentsMargins(0, 0, 4, 0);
detailsLayout->setSpacing(10);
auto* name = new fluent::textfields::Label(QStringLiteral("Design guidelines"), details);
name->setFluentTypography(Typography::FontRole::BodyStrong);
name->setWordWrap(true);
detailsLayout->addWidget(name);
for (const auto& text : {QStringLiteral("Markdown document"), QStringLiteral("Shared layouts, typography and component guidance."), QStringLiteral("Updated today")}) {
    auto* label = new fluent::textfields::Label(text, details);
    label->setWordWrap(true);
    label->setTextColorRole(fluent::textfields::Label::TextColorRole::Secondary);
    detailsLayout->addWidget(label);
}
detailsLayout->addStretch();
scroll->setWidget(details);
panelLayout->addWidget(scroll, 1);
control->setContentWidget(panel);
QObject::connect(openButton, &fluent::basicinput::Button::clicked, control, &fluent::collections::DrawerView::open);
QObject::connect(closeButton, &fluent::basicinput::Button::clicked, control, &fluent::collections::DrawerView::close);
